import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), k = nextInt();
        HashMap<Long, int[]> table = new HashMap<>();
        int[] best = new int[k + 1];
        for (int i = 0; i < n; i++) {
            int[] row = table.computeIfAbsent(nextLong(), x -> new int[k + 1]);
            // row[j]: longest subsequence ending with this value using at most j changes.
            for (int j = k; j >= 0; j--) {
                row[j] = Math.max(row[j] + 1, j > 0 ? best[j - 1] + 1 : 1);
                best[j] = Math.max(best[j], row[j]);
            }
        }
        System.out.println(best[k]);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := int(nextInt()), int(nextInt())
	table := map[int64][]int{}
	best := make([]int, k+1)
	for i := 0; i < n; i++ {
		value := nextInt()
		row, ok := table[value]
		if !ok {
			row = make([]int, k+1)
			table[value] = row
		}
		// row[j]: longest subsequence ending with this value using at most j changes.
		for j := k; j >= 0; j-- {
			c := 1
			if j > 0 {
				c = best[j-1] + 1
			}
			row[j] = max(row[j]+1, c)
			best[j] = max(best[j], row[j])
		}
	}
	fmt.Println(best[k])
}
